package org.apache.commons.lang.text;

import java.io.*;
import java.io.Reader;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ArrayUtils;
import org.apache.commons.lang.SystemUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class StrBuilder_indexOf_TriageGen2Test {

    @Test
    public void testIndexOf_NullString() {
        StrBuilder sb = new StrBuilder("hello");
        Assert.assertEquals(-1, sb.indexOf(null, 0));
    }

    @Test
    public void testIndexOf_StartIndexOutOfBounds() {
        StrBuilder sb = new StrBuilder("hello");
        // startIndex >= size
        Assert.assertEquals(-1, sb.indexOf("e", 5));
        Assert.assertEquals(-1, sb.indexOf("e", 10));
    }

    @Test
    public void testIndexOf_NegativeStartIndex() {
        // startIndex < 0 should be treated as 0
        StrBuilder sb = new StrBuilder("hello");
        Assert.assertEquals(1, sb.indexOf("e", -5));
    }

    @Test
    public void testIndexOf_EmptySearchString() {
        // if (strLen == 0) return startIndex;
        StrBuilder sb = new StrBuilder("hello");
        Assert.assertEquals(0, sb.indexOf("", 0));
        Assert.assertEquals(3, sb.indexOf("", 3));
    }

    @Test
    public void testIndexOf_SingleCharString() {
        // if (strLen == 1) return indexOf(str.charAt(0), startIndex);
        StrBuilder sb = new StrBuilder("hello");
        Assert.assertEquals(1, sb.indexOf("e", 0));
        Assert.assertEquals(4, sb.indexOf("o", 0));
        Assert.assertEquals(-1, sb.indexOf("z", 0));
    }

    @Test
    public void testIndexOf_SearchStringLongerThanBuilder() {
        // if (strLen > size) return -1;
        StrBuilder sb = new StrBuilder("abc");
        Assert.assertEquals(-1, sb.indexOf("abcd", 0));
    }

    @Test
    public void testIndexOf_FoundAtStart() {
        StrBuilder sb = new StrBuilder("apple");
        Assert.assertEquals(0, sb.indexOf("app", 0));
    }

    @Test
    public void testIndexOf_FoundInMiddle() {
        StrBuilder sb = new StrBuilder("apple");
        Assert.assertEquals(1, sb.indexOf("ppl", 0));
    }

    @Test
    public void testIndexOf_FoundAtEnd() {
        StrBuilder sb = new StrBuilder("apple");
        Assert.assertEquals(2, sb.indexOf("ple", 0));
    }

    @Test
    public void testIndexOf_NotFound() {
        StrBuilder sb = new StrBuilder("apple");
        Assert.assertEquals(-1, sb.indexOf("xyz", 0));
        Assert.assertEquals(-1, sb.indexOf("appz", 0));
    }

    @Test
    public void testIndexOf_WithStartIndexOffset() {
        StrBuilder sb = new StrBuilder("banana");
        // "ana" occurs at index 1 and index 3
        Assert.assertEquals(1, sb.indexOf("ana", 0));
        Assert.assertEquals(3, sb.indexOf("ana", 2));
        Assert.assertEquals(-1, sb.indexOf("ana", 4));
    }

    @Test
    public void testIndexOf_PartialMatchThenFail() {
        // Tests the 'continue outer' logic
        StrBuilder sb = new StrBuilder("abacaba");
        // Searching for "abc"
        // i=0: 'a'=='a', 'b'=='b', 'a'!='c' -> continue outer
        // i=1: 'b'!='a' -> continue outer
        // i=2: 'a'=='a', 'c'=='c', 'a'!='b' -> continue outer...
        Assert.assertEquals(-1, sb.indexOf("abc", 0));
    }

    @Test
    public void testIndexOf_BoundaryCondition_LoopLimit() {
        // len = thisBuf.length - strLen; 
        // The loop runs i < len. 
        // Note: There is a potential logic bug in the provided source code 
        // where if len is exactly the last possible index, the loop might skip the last possible match.
        // However, we test based on the provided implementation.
        StrBuilder sb = new StrBuilder("abc");
        // size = 3, strLen = 2, len = 3 - 2 = 1. 
        // Loop i = 0; i < 1; i++ -> only checks index 0.
        // This means "bc" at index 1 will NOT be found because i must be < 1.
        // We write the test to reflect the provided code's behavior.
        Assert.assertEquals(-1, sb.indexOf("bc", 0));
    }
}
